    long long v12x = x[1] - x[0];
    long long v12y = y[1] - y[0];
    long long v13x = x[2] - x[0];
    long long v13y = y[2] - y[0];

    long long dot = v12x * v13x + v12y * v13y;
    if (dot <= 0) ok = 0;

    // 2. |P1P2| == |P1P3|
    long long d12 = v12x * v12x + v12y * v12y;
    long long d13 = v13x * v13x + v13y * v13y;
    if (d12 != d13) ok = 0;

    // Base vector P2 -> P3
    long long bx = x[2] - x[1];
    long long by = y[2] - y[1];

    // 3. P2, P3, P4 and P5 are collinear
    long long cross4 = bx * (y[3] - y[1]) - by * (x[3] - x[1]);
    long long cross5 = bx * (y[4] - y[1]) - by * (x[4] - x[1]);
    if (cross4 != 0 || cross5 != 0) ok = 0;

    // 4. Midpoints of P2P3 and P4P5 coincide
    if (x[1] + x[2] != x[3] + x[4] || y[1] + y[2] != y[3] + y[4]) ok = 0;

