    long long d45 = v45x * v45x + v45y * v45y;
    if (d23 <= d45) ok = 0;

    // 6. P4P6 and P5P7 are perpendicular to P2P3
    long long v46x = x[5] - x[3];
    long long v46y = y[5] - y[3];
    long long v57x = x[6] - x[4];
    long long v57y = y[6] - y[4];

    if (v46x * bx + v46y * by != 0) ok = 0;
    if (v57x * bx + v57y * by != 0) ok = 0;

    // 7. |P4P6| == |P5P7|
    long long d46 = v46x * v46x + v46y * v46y;
    long long d57 = v57x * v57x + v57y * v57y;
    if (d46 != d57) ok = 0;

    // 8. P1 and P6 are on opposite sides of line P2P3
    long long crossP1 = bx * (y[0] - y[1]) - by * (x[0] - x[1]);
    long long crossP6 = bx * (y[5] - y[1]) - by * (x[5] - x[1]);

    if (!((crossP1 > 0 && crossP6 < 0) || (crossP1 < 0 && crossP6 > 0))) {
        ok = 0;
    }

    printf("%c\n", ok ? 'S' : 'N');
    return 0;
}
